import random

def play_game():
    """Play a game of rock, paper, scissors against the computer."""
    print("Welcome to the game of rock, paper, scissors!")

    # Define the possible choices
    choices = ["rock", "paper", "scissors"]

    # Get the user's choice
    user_choice = input("Enter your choice (rock, paper, scissors): ").lower()

    # Ensure the user's choice is valid
    while user_choice not in choices:
        print("Invalid choice. Please enter 'rock', 'paper', or 'scissors'.")
        user_choice = input("Enter your choice (rock, paper, scissors): ").lower()

    # Get the computer's choice
    computer_choice = random.choice(choices)

    # Determine the winner
    if user_choice == "rock":
        if computer_choice == "scissors":
            print(f"You win! Rock beats scissors.")
        else:
            print(f"You lose! Scissors beats rock.")
    elif user_choice == "paper":
        if computer_choice == "rock":
            print(f"You win! Paper covers rock.")
        else:
            print(f"You lose! Rock beats paper.")
    elif user_choice == "scissors":
        if computer_choice == "paper":
            print(f"You win! Scissors cut paper.")
        else:
            print(f"You lose! Paper beats scissors.")
    else:
        raise ValueError("Invalid choice.")

# Call the function to start the game
play_game()
```
